mapper.select:
/** * selectCnnctChatConsttList : isry.couns.mngr.consttChc.ConsttChcMapper : 잇는채팅 상담선택 화면 조회 */
SELECT BB.USER_ID AS CNSLTNT_ID /** 상담자 아이디 **/ , C##RG.DEC_B64(DD.FLNM_ENCPT) AS CNSLTNT_NM /** 상담자 이름 **/ , CC.DEPT_NM AS DEPT_NM /** 소속 부서 이름 **/ , CASE WHEN AA.CONSTT_ID IS NULL THEN 'N' ELSE 'Y' END AS CKB_CONSTT_YN /** 상담자 선택 여부 **/ FROM AYC470 AA /** 잇는 채팅 상담자 **/ , SAA200 BB /** 사용자 **/ , SAA300 CC /** 기관부서 **/ , SCA100 DD /** 종사자 **/ WHERE 1=1
AND DD.OGDP_DEPT_CD = #{deptCd}
AND AA.CONSTT_ID(+) = BB.USER_ID AND DD.ENFSN_NO = BB.ENFSN_NO(+) /* 종사자번호 */ AND DD.DEL_YN = 'N' /* 종사자 삭제여부 */ AND CC.DEPT_CD = DD.OGDP_DEPT_CD

mapper.insert:
INSERT
	INTO	AYC470			/** 잇는채팅 상담자 **/
	(
			CONSTT_ID		/** 상담자 아이디 **/
		,	CONSTT_NM_ENCPT		/** 상담자 이름 **/
		,	REG_YMD				
	)
VALUES



	(
			#{item.CNSLTNT_ID}
		,	#{item.CNSLTNT_NM}
		,	TO_CHAR(SYSDATE,'YYYYMMDD')				
	)
